// bytes's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, bytesMethods, and the member entries of docs/reference/types/bytes.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness, which is non-emptiness: `!!x` ⟺ `x != bytes()`.
//
//kavun:member is_true pure () -> bool
func bytesIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// ```go
// bytes("hi").format("v")     // => "bytes([104, 105])"
// ```
//
//kavun:member format pure ([spec]) -> string
func bytesFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Answer a copy of the elements from `start` to `end`; bounds **clamp** (contrast `splice`, which raises), negative
// indices count from the end.
//
// `slice(i, j)` **clamps**.
//
// ```go
// bytes("abc").slice(1, 99)       // => bytes([98, 99]) — clamps
// ```
//
//kavun:member slice pure ([start[, end]]) -> bytes
func bytesSlice(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, e, err := readSliceArgs(id.String(), args)
	if err != nil {
		return Undefined, err
	}
	return v.Slice(s, e)
}

// Answer an independent, mutable copy.
//
//kavun:member copy pure () -> bytes
func bytesCopy(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return bytesTypeCopy(v, true)
}

// Answer a deep-immutable *copy*; the source and its aliases are untouched.
//
// The copy's type name is `immutable-bytes`.
//
//kavun:member freeze pure () -> bytes
func bytesFreeze(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return v.Freeze()
}

// Answer a new, independent, mutable copy, exactly `bytes(b)` / `b.copy()`.
//
// ```go
// bytes("ab").bytes()         // a NEW, independent, mutable copy — same as bytes(b), not the receiver
// b"ab".bytes()               // the writable-buffer idiom: a literal's constant body, copied
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member bytes pure ([default]) -> bytes
func bytesBytes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	c, err := bytesTypeCopy(v, false)
	if err != nil {
		return Undefined, err
	}
	return ConvMember(id.String(), bytesTypeName, args, true, c)
}

// Answer the octets as an array of `byte` elements, without decoding.
//
// `.array()` materialises the octets as `byte` elements — no decoding.
