// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member string pure ([default]) -> string
func bytesString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Bytes)(v.Ptr)
	return ConvMember(id.String(), bytesTypeName, args, true, NewStringValue(string(o.Elements)))
}

