// Report whether an element, a run, a member of a set or a predicate match occurs; with no argument, whether any
// element is significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `contains` takes the full menu: element, run, homogeneous variadic set, predicate, or absent.
// `contains(fn)` ≡ `any(fn)` and `contains()` ≡ `any()`.
//
// ```go
// bytes("héllo").contains("éll")      // => true — its UTF-8 octet run
// bytes("abc").contains(b'x', b'b')   // => true — set
// bytes("abc").contains(func(x) { return x > b'b' })   // => true
// ```
//
//kavun:member contains pure (...x) -> bool
func bytesContains(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The empty run is contained everywhere, the same answer `in` gives.
	m, err := bytesReadMatchArgs(vm, "contains", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := (*Bytes)(v.Ptr).Elements

	if m.runs != nil {
		for _, r := range m.runs {
			if len(r) == 0 {
				return True, nil
			}
		}
		for i := range elems {
			if seq.RunLengthAt(elems, i, m.runs) > 0 {
				return True, nil
			}
		}
		return False, nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Count the matches of an element, a run (non-overlapping occurrences), a set or a predicate; with no argument, the
// significant elements.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// ```go
// bytes("banana").count(b'a')         // => 3
// ```
//
//kavun:member count pure (...x) -> int
func bytesCount(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := bytesReadMatchArgs(vm, "count", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := (*Bytes)(v.Ptr).Elements

	n := int64(0)
	if m.runs != nil {
		for i := 0; i < len(elems); {
			if k := seq.RunLengthAt(elems, i, m.runs); k > 0 {
				n++
				i += k
			} else {
				i++
			}
		}
		return IntValue(n), nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			n++
		}
	}
	return IntValue(n), nil
}

// Keep only the matches of an element, a run, a set or a predicate; with no argument, the significant elements; see
// [`remove`](#remove).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member keep pure (...x) -> bytes
func bytesKeep(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := bytesKept(vm, "keep", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewBytesValue(out, false), nil
}

// In-place twin of `keep`.
//
//kavun:member keep_in_place impure (...x) -> bytes
func bytesKeepInPlace(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "keep_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := bytesKept(vm, name, v, args)
	if err != nil {
		return Undefined, err
	}
	(*Bytes)(v.Ptr).Set(out)
	return v, nil
}

// Remove every match of an element, a run, a set or a predicate; with no argument, the elements of the
